import React from 'react';
import { Link } from 'react-router-dom';

const AdminDashboard = () => {
  return (
    <div>
      <h1>Admin Dashboard</h1>
      <p>Welcome, Admin!</p>
      <nav>
        <ul>
          <li><Link to="/admin-dashboard/students">Student Management</Link></li>
          <li><Link to="/admin-dashboard/teachers">Teacher Management</Link></li>
        </ul>
      </nav>
    </div>
  );
};

export default AdminDashboard;
